const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define northern Madagascar region (latitude -12 to -15)
  const region = ee.Geometry.Rectangle([42.5, -15, 50.5, -12]);

  // Function to calculate total precipitation for Dec-Jan period
  function getPrecipitationTotal(startYear, endYear) {
    const collection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterBounds(region)
      .filter(ee.Filter.calendarRange(12, 1, 'month'))
      .filter(ee.Filter.calendarRange(startYear, endYear, 'year'));

    return collection.sum().set('period', `${startYear}-${endYear}`);
  }

  // Get recent period (Dec 2018 - Jan 2019)
  const recentPeriod = getPrecipitationTotal(2018, 2019);

  // Get long-term average (Dec-Jan from 2000-2019, excluding 2018-2019)
  const longTermCollection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterBounds(region)
    .filter(ee.Filter.calendarRange(12, 1, 'month'))
    .filter(ee.Filter.calendarRange(2000, 2019, 'year'));

  // Check collection sizes
  const recentSize = recentPeriod.bandNames().size().getInfo();
  const longTermSize = longTermCollection.size().getInfo();

  console.log(`Recent period images: ${recentSize}`);
  console.log(`Long-term collection size: ${longTermSize}`);

  if (recentSize === 0 || longTermSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate long-term average
  const longTermAvg = longTermCollection.mean();

  // Calculate mean precipitation values
  const recentMean = recentPeriod.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const longTermMean = longTermAvg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // Check for valid pixels
  const recentCount = recentPeriod.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const longTermCount = longTermAvg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Recent period pixels: ${recentCount}`);
  console.log(`Long-term pixels: ${longTermCount}`);

  if (recentCount === 0 || longTermCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  console.log(`Recent (2018-19): ${recentMean?.toFixed(2)} mm`);
  console.log(`Long-term avg: ${longTermMean?.toFixed(2)} mm`);

  // Validate results
  if (recentMean === null || longTermMean === null || 
      isNaN(recentMean) || isNaN(longTermMean) ||
      recentMean < 0 || longTermMean < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare and output answer
  if (recentMean < longTermMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
